(6, 'HT-2026-006', '公众号代运营服务合同', '2', '本企业', 'XX营销策划公司', 60000.00, '2026-05-01', '2026-05-15', '2027-05-14', '0', 7, NULL, '0', '1', '2026-06-02T10:06:27', NULL, '2026-06-02T10:06:27');
INSERT INTO `oa_document` (`id`, `title`, `content`, `category_id`, `emp_id`, `file_url`, `status`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES
(1, '员工考勤管理制度', '第一章 总则\n第一条 为加强公司考勤管理，规范员工出勤行为，保障正常的工作秩序，特制定本制度。\n\n第二章 作息时间\n第二条 公司实行每周五天工作制，工作时间为上午9:00-12:00，下午13:00-18:00。', 1, 5, '/uploads/docs/attendance_policy.pdf', 1, '0', '5', '2026-01-15T09:00', NULL, '2026-06-02T10:05:17'),
(2, '差旅费报销管理办法', '为加强差旅费管理，合理控制费用支出，根据国家有关规定，结合公司实际情况，制定本办法。\n\n本办法适用于公司全体员工因公出差的差旅费报销。', 3, 6, '/uploads/docs/travel_policy.pdf', 1, '0', '6', '2026-02-01T10:00', NULL, '2026-06-02T10:05:17'),
(3, '2026年度人力资源规划', '一、总体目标\n2026年度人力资源工作围绕公司发展战略，优化人才结构，加强队伍建设。\n\n二、人才引进计划\n计划招聘各类人才30人，其中包括技术研发15人、市场营销8人、行政管理7人。', 4, 5, '/uploads/docs/hr_plan_2026.pdf', 1, '0', '5', '2026-01-10T14:00', NULL, '2026-06-02T10:05:17'),
(4, '信息安全管理制度', '为保障公司信息系统安全稳定运行，保护公司信息资源安全，依据《网络安全法》制定本制度。\n\n本制度适用于公司所有信息系统的使用和管理。', 1, 1, '/uploads/docs/security_policy.pdf', 1, '0', '1', '2026-03-01T16:00', NULL, '2026-06-02T10:05:17'),
(5, '采购管理制度', '第一章 总则\n为规范采购行为，保证采购质量，降低采购成本，提高资金使用效益，特制定本制度。\n\n第二章 采购方式\n公司采购分为：公开招标、邀请招标、竞争性谈判、询价采购和单一来源采购。', 1, 6, '/uploads/docs/procurement_policy.pdf', 1, '0', '6', '2026-03-15T09:30', NULL, '2026-06-02T10:05:17'),
(6, '关于公司组织架构调整的通知', '根据公司发展需要，经研究决定，对公司组织架构做如下调整：\n1. 成立研发中心，下设研发一组和研发二组；\n2. 市场部和销售部合并为市场营销中心。', 2, 1, '/uploads/docs/org_restructure.pdf', 1, '0', '1', '2026-04-01T11:00', NULL, '2026-06-02T10:05:17'),
(7, '技术架构白皮书 v3.0', '本文档描述了公司技术架构的整体设计，包括系统架构、技术选型、模块划分等内容。\n适用对象：技术研发团队。\n版本历史：v3.0 新增微服务架构说明。', 5, 10, '/uploads/docs/tech_arch_v3.pdf', 1, '0', '10', '2026-05-10T15:00', NULL, '2026-06-02T10:05:17'),
(8, '2026上半年度财务报告', '一、收入情况\n2026年上半年公司实现营业收入5,200万元，同比增长15%。\n\n二、支出情况\n营业成本3,100万元，管理费用800万元，销售费用500万元。\n\n三、利润情况\n净利润800万元，同比增长12%。', 3, 6, '/uploads/docs/finance_h1_2026.pdf', 1, '0', '6', '2026-05-20T17:00', NULL, '2026-06-02T10:05:17'),
(9, '保密协议范本', '本保密协议（以下简称"协议"）由以下双方于____年__月__日签订。\n\n甲方：[公司名称]\n乙方：[员工姓名]\n\n双方本着平等自愿的原则，就保密事宜达成如下协议...', 4, 5, '/uploads/docs/nda_template.docx', 1, '0', '5', '2026-01-05T08:00', NULL, '2026-06-02T10:05:17'),
(10, 'API接口规范文档', '本文档定义了系统各模块之间的API接口规范。\n\n规范要求：\n1. RESTful风格\n2. 统一响应格式\n3. 版本管理\n4. 错误码定义', 5, 10, '/uploads/docs/api_standards.pdf', 1, '0', '10', '2026-04-15T13:00', NULL, '2026-06-02T10:05:17'),
(11, '公司车辆使用管理办法', '第一章 总则\n为加强公司车辆管理，提高车辆使用效率，降低运营成本，特制定本办法。\n\n第二章 车辆使用\n公司车辆由行政部统一调度，使用需提前申请。', 1, 15, '/uploads/docs/vehicle_policy.pdf', 1, '0', '15', '2026-02-20T10:00', NULL, '2026-06-02T10:05:17'),
(12, '员工手册（2026修订版）', '欢迎加入本公司！本手册旨在帮助您了解公司的文化、政策和规定。\n\n新员工入职须知：\n1. 入职材料准备\n2. 社保公积金办理\n3. 培训安排\n4. 试用期考核', 4, 5, '/uploads/docs/employee_handbook_2026.pdf', 1, '0', '5', '2026-01-01T09:00', NULL, '2026-06-02T10:05:17'),
(13, '模拟公文 #019', '模拟公文正文，用于公文列表、分类、归档状态测试。批次：mock_other_20260609093237', 4, 1, '/mock/document/mock_other_20260609093237/019.pdf', 1, '0', 'mock_other_20260609093237', '2026-06-08T22:32:37', 'mock_other_20260609093237', '2026-06-08T22:32:37'),
