INSERT INTO `oa_notice` (`id`, `title`, `content`, `type`, `emp_id`, `status`, `is_top`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES
(1, '关于2026年端午节放假安排的通知', '公司各部门：\n根据国家法定节假日安排，2026年端午节放假时间为：6月25日（星期四）至6月27日（星期六），共3天。6月28日（星期日）正常上班。\n请各部门做好节前安全检查工作，确保办公区域水电门窗关闭。', 0, 1, 1, '1', '0', '1', '2026-05-20T09:00', NULL, '2026-06-02T10:03:41'),
(2, '2026年度优秀员工评选通知', '为表彰先进，树立榜样，公司决定开展2026年度优秀员工评选活动。\n评选条件：\n1. 入职满一年以上；\n2. 年度绩效考核优秀；\n3. 无重大违纪记录。\n请各部门于6月15日前推荐候选人。', 1, 1, 1, '1', '0', '1', '2026-05-25T10:30', NULL, '2026-06-02T10:03:41'),
(3, '办公区管理制度更新', '为进一步规范办公区域管理，营造良好的办公环境，现将更新后的办公区管理制度公布如下：\n1. 办公区域禁止吸烟，吸烟请至指定吸烟区；\n2. 会议室使用需提前在系统预约；\n3. 下班前请关闭电脑和照明电源。\n本制度自发布之日起执行。', 2, 1, 1, '1', '0', '1', '2026-05-18T14:00', NULL, '2026-06-02T10:03:41'),
(4, '新员工入职培训通知（2026年第三期）', '人力资源部将于6月10日-11日举办2026年第三期新员工入职培训。\n培训地点：第一会议室\n培训内容：公司文化、规章制度、OA系统操作\n参训人员：2026年4月后入职员工', 0, 5, 1, '0', '0', '5', '2026-06-01T08:30', NULL, '2026-06-02T10:03:41'),
(5, '关于启用新版本OA系统的通知', '各位同事：\nOA办公系统已完成升级，新版本优化了审批流程和界面体验。\n主要更新：\n1. 新增移动端审批功能；\n2. 优化请假/报销流程；\n3. 修复已知问题。\n如有问题请联系信息技术部。', 1, 1, 1, '0', '0', '1', '2026-05-15T16:00', NULL, '2026-06-02T10:03:41'),
(6, '薪资发放时间调整通知', '财务部通知：自2026年6月起，薪资发放时间调整为每月10日（如遇节假日顺延）。请各部门考勤员于每月5日前提交考勤汇总表。', 0, 6, 1, '0', '0', '6', '2026-05-30T11:00', NULL, '2026-06-02T10:03:41'),
(7, '2026年度员工体检通知', '关爱员工健康，公司组织2026年度体检。\n体检机构：市中心医院体检中心\n时间安排：6月15日-6月30日（分批前往）\n注意事项：空腹前往，体检前一天注意休息。', 1, 5, 1, '0', '0', '5', '2026-06-01T09:00', NULL, '2026-06-02T10:03:41'),
(8, '公司机房维护公告', '信息技术部计划于6月5日(周六)22:00-24:00进行机房设备维护。届时OA系统、邮件系统将暂停服务。请各位提前做好工作安排。', 1, 1, 1, '0', '0', '1', '2026-06-02T10:00', NULL, '2026-06-02T10:03:41'),
(9, '夏季高温补贴发放标准', '根据公司福利制度，6月-9月期间向全体员工发放高温补贴。标准如下：\n户外作业人员：300元/月\n室内工作人员：150元/月\n随每月薪资发放。', 0, 6, 1, '0', '0', '6', '2026-05-28T15:30', NULL, '2026-06-02T10:03:41'),
(10, '部门预算编制工作启动', '请各部门于6月20日前完成2026年下半年预算编制工作。预算编制表已发至各部门负责人邮箱，请按时提交至财务部。', 0, 6, 1, '0', '0', '6', '2026-06-01T14:00', NULL, '2026-06-02T10:03:41'),
(11, '关于规范差旅费报销的通知', '为进一步规范差旅费管理，现将报销标准重申如下：\n住宿费：一线城市≤500元/天，其他城市≤350元/天\n伙食补贴：一线城市120元/天，其他城市100元/天\n交通费：凭票据实报实销', 2, 6, 1, '0', '0', '6', '2026-05-22T09:30', NULL, '2026-06-02T10:03:41'),
(12, '五一劳动节放假通知', '2026年五一劳动节放假安排：4月30日（星期四）至5月4日（星期一），共5天。4月28日（星期日）和5月9日（星期六）补班。', 0, 1, 1, '0', '0', '1', '2026-04-25T10:00', NULL, '2026-06-02T10:03:41'),
(13, '信息安全培训通知', '公司将于6月12日举办信息安全专题培训，请全体员工参加。\n内容：密码安全、钓鱼邮件识别、数据保护\n地点：多功能厅\n时间：14:00-16:00', 0, 1, 1, '0', '0', '1', '2026-06-01T16:30', NULL, '2026-06-02T10:03:41'),
(14, '公司知识产权管理办法', '为加强公司知识产权保护，现发布《知识产权管理办法》。\n主要内容：\n1. 员工在职期间创造的职务成果归公司所有；\n2. 离职时需归还所有公司资料；\n3. 违反者将追究法律责任。', 2, 1, 1, '0', '0', '1', '2026-05-20T13:00', NULL, '2026-06-02T10:03:41'),
(15, '2026年度团建活动方案征集', '为增强团队凝聚力，公司计划于7月开展年度团建活动。现面向全体员工征集活动方案建议。\n请于6月20日前将方案发送至行政部邮箱。', 0, 15, 1, '0', '0', '15', '2026-06-02T09:00', NULL, '2026-06-02T10:03:41'),
(16, '模拟公告 #024', '模拟公告内容，覆盖通知、公告、制度三类数据。批次：mock_other_20260609093237', 0, 2, 1, '0', '0', 'mock_other_20260609093237', '2026-06-09T03:32:37', 'mock_other_20260609093237', '2026-06-09T03:32:37'),
