  `runtime_schema` longtext COLLATE utf8mb4_general_ci COMMENT 'Backend normalized runtime schema JSON',
  `bpmn_xml` longtext COLLATE utf8mb4_general_ci COMMENT 'Optional BPMN 2.0 XML export',
