-- ------------------------------------------------------------
-- Table: wf_process_instance
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `wf_process_instance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '娴佺▼瀹炰緥ID',
  `process_id` bigint NOT NULL COMMENT '娴佺▼瀹氫箟ID',
  `business_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '涓氬姟绫诲瀷',
  `business_id` bigint NOT NULL COMMENT '涓氬姟ID',
  `initiator_id` bigint NOT NULL COMMENT '鍙戣捣浜篒D',
