  `condition_context` text COLLATE utf8mb4_general_ci COMMENT '鏉′欢涓婁笅鏂嘕SON',
  `status` char(1) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '鐘舵?(0杩愯?涓?1宸查?杩?2宸查┏鍥?3宸叉挙鍥?',
  `start_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍙戣捣鏃堕棿',
  `end_time` datetime DEFAULT NULL COMMENT '缁撴潫鏃堕棿',
  `del_flag` char(1) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '鍒犻櫎鏍囧織(0瀛樺湪 1鍒犻櫎)',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '鍒涘缓浜',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `active_nodes` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '閫楀彿鍒嗛殧鐨勬椿鍔ㄨ妭鐐笽D(骞惰?缃戝叧)',
  `snapshot_node_config` text COLLATE utf8mb4_general_ci COMMENT '娴佺▼鍚?姩鏃剁殑鑺傜偣閰嶇疆蹇?収',
  `parent_instance_id` bigint DEFAULT NULL COMMENT '鐖舵祦绋嬪疄渚婭D(瀛愭祦绋嬪祵濂?',
  `process_version` int DEFAULT NULL COMMENT '娴佺▼瀹氫箟鐗堟湰鍙',
  PRIMARY KEY (`id`),
  KEY `idx_process_id` (`process_id`),
  KEY `idx_business` (`business_type`,`business_id`),
  KEY `idx_initiator_id` (`initiator_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=792 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='娴佺▼瀹炰緥琛';


-- ------------------------------------------------------------
-- Table: wf_task
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `wf_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '浠诲姟ID',
  `instance_id` bigint NOT NULL,
